class CheckSide Effects {
    private final CheckLevel level;
    private staticfinal List[node] problemNodes;
    private staticfinal JavaObject model;

    public CheckSide Effects() {
        level = CheckLevel.PRODUCT;
        problemNodes = new ArrayList[]();
        model = new net javascript.rhino.CheckObjectModel(new net javascript.rhino checklist());
    }

    @Override
    public void setup(node n) throws IllegalArgumentException {
        // Setup the code in a separate block
        if (n.isEmpty() || isComma(n)) {
            return;
        }

        if (parent == null) {
            // No change to parent-child relationship
            return;
        }

        // Remove one side effect from the node.
        if (n.isNamespace() && !isStatement(n.parent)) {
            return;
        }

        try {
            // Do nothing for block-level expressions
            if (!isExpressionResult(n) && !isBlock(n) && isStatement(n.parent) &&
                    !NodeUtil.mayHaveSideEffects(n, t.getCompiler())) {
                // We've already handled this with the method `node.subscript(node).replaceSideEffect()`
                return;
            }

        catch (InvalidAccessError e) {
            if (!isStatement(n)) {
                problemNodes.add(n);
            }
        } else {
            node.isSubscript();
        }
    }
}
