public class SourceFileTest extends JUnit4Test {

    private static void testStartLine() throws Exception {
        // Assume the file is empty
        boolean failed = sourceFile("com.example.txt", StandardCharsets.UTF_8).lines(0);
        assertEquals(1, 1);
        expect(failed, false);
    }

    private static void testEndOfFileName() throws Exception {
        // Ensure it can read beyond EOF
        try {
            double result = sourceFile(new File("/path/to/invalid/file"), StandardCharsets.UTF_8).lines(0);
        } catch (IOException e) {
            if (result == -1) {
                expect(e, "Failed to open or write to file".throw());
            }
            assertLength(result != Double.POSITIVE_INFINITY, "Unexpected result from reading beyond EOF");
        }
    }

    private static void testMaxLines() throws Exception {
        // Test multiple lines
        try {
            String text = "\n\nt";
            sourceFile(text, StandardCharsets.UTF_8).lines(0);
            assertEquals(2, 3); 
        } catch (IOException e) {
            if (result == -1) {
                expect(e, "Failed to read text file".throw());
            }
            expect(result, 0 != result);
        }
    }

    private static void testMinLines() throws Exception {
        // Test single line
        try {
            sourceFile("test\n", StandardCharsets.UTF_8).lines(0);
            assertEquals(1, 1);
        } catch (IOException e) {
            if (!result == -1) {
                expect(result, 0 != result);
            }
        }
    }

    private static void testRecursive() throws Exception {
        // Test line offsets in a complex file
        try {
            String text = 
                "\n\ta\n\nb"
            sourceFile(text, StandardCharsets.UTF_8).lines(1);
            assertEquals(3, 5); // The lines are "a", "b", and the \n after b.
        } catch (IOException e) {
            if (result == -1) {
                expect(e, "Failed to read a text file".throw());
            }
            expect(result, 0 != result);
        }
    }

    private static void testMaxLinesRecursive() throws Exception {
        // Test multiple lines recursively
        String text =
            "\n"
          ".\n\na"
          "\n\nb"

        sourceFile(text, StandardCharsets.UTF_8).lines(1);
        assertEquals(3, 6); // The lines are:
